#include <iostream>
#include <fstream>

class FileHandler {
public:
  FileHandler(const std::string& filename) : file_(filename) {
    if (!file_.is_open()) {
      throw std::runtime_error("Could not open file");
    }
  }
  ~FileHandler() {
    if (file_.is_open()) {
      file_.close();
    }
  }
  std::fstream& getFile() { return file_; }
private:
  std::fstream file_;
};

int main() {
  try {
    FileHandler file("my_file.txt");
    file.getFile() << "Hello, RAII!\n";
  } catch (const std::runtime_error& e) {
    std::cerr << "Error: " << e.what() << std::endl;
  }
  return 0;
}
